var ASSET_META = {"ref":{"fw":24,"fh":32},"body1":{"fw":28,"fh":28},"body2":{"fw":28,"fh":28}};
Object.keys(ASSETS).forEach(function (k) { ASSETS[k] = ASSETS[k].replace(/~/g, '/'); });
