  var g = sc.add.graphics().setDepth(3);
  g.fillStyle(0xffffff, 0.85).fillRect(MID - 1, COURT.y, 2, COURT.h);
  g.fillStyle(0xffffff, 0.35).fillCircle(MID, COURT.y + COURT.h / 2, 3);
